"""A5 Easel painting: schools and movements (mostly artist-led)."""
from common import *


def A(axis, groups=None, order=None, add=None, cat=None, home=None, **kw):
    d = dict(artist_led=True, axis=axis, regroup=G(groups or {}), order=order or list((groups or {}).keys()), add=add or [], cat=cat or [], home=home)
    d.update(kw)
    return d


